// Temporary verification for the createdAt column fix. Deleted after running.
import { execFile, spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import puppeteer from 'puppeteer-core';

const repoRoot = process.argv[2];
const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
process.env.TZ = 'UTC'; // force UTC so offset-conversion assertions are deterministic

const records = [
  // 0: valid Zulu
  '{"id":"r-z","name":"z","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":"2026-02-03T08:30:00Z"}',
  // 1: valid with +05:30 offset -> UTC instant 2026-03-14T19:32:03Z
  '{"id":"r-off","name":"off","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":"2026-03-15T01:02:03+05:30"}',
  // 2: unparseable plain Chinese
  '{"id":"r-bad","name":"bad","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":"日期待补"}',
  // 3: unparseable with angle brackets / quotes / ampersand / entity-like text
  '{"id":"r-xss","name":"xss","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":"<b>hi</b> & \\"q\\" &lt;img&"}',
  // 4: field missing
  '{"id":"r-missing","name":"missing","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting"}',
  // 5: explicit null
  '{"id":"r-null","name":"nul","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":null}',
  // 6: empty string
  '{"id":"r-empty","name":"emp","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":""}',
  // 7: object -> abnormal cell
  '{"id":"r-obj","name":"obj","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":{"v":"2026-03-05T00:00:00Z"}}',
  // 8: array -> abnormal cell
  '{"id":"r-arr","name":"arr","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":["2026-03-05T00:00:00Z"]}',
];

const binDir = await mkdtemp(path.join(tmpdir(), 'verify-bin-'));
const dataDir = await mkdtemp(path.join(tmpdir(), 'verify-data-'));
const serverBin = path.join(binDir, 'score-arena');
await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + records.join(',\n') + '\n]\n');

const proc = spawn(serverBin, ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
  { stdio: ['ignore', 'pipe', 'inherit'] });
let baseURL;
try {
  baseURL = await new Promise((resolve, reject) => {
    let buf = '';
    const timer = setTimeout(() => reject(new Error('listen timeout')), 15000);
    proc.stdout.on('data', (c) => {
      buf += c;
      const m = buf.match(/listening on (http:\/\/\S+)/);
      if (m) { clearTimeout(timer); resolve(m[1]); }
    });
  });

  const browser = await puppeteer.launch({
    executablePath: chromePath, headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
  });
  const page = await browser.newPage();
  await page.goto(baseURL, { waitUntil: 'load' });
  await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 9);

  const rows = await page.$$eval('#list-area table tbody tr', (trs) =>
    trs.map((tr) => {
      const td = tr.querySelectorAll('td')[6];
      return {
        text: td.textContent,
        title: td.getAttribute('title'),
        html: td.innerHTML,
      };
    }));
  const list = await page.evaluate(() => ({
    hasTable: !!document.querySelector('#list-area table'),
    skip: document.querySelectorAll('#list-area .skip-notice').length,
    err: !!document.querySelector('#list-area .list-error'),
  }));

  const checks = [
    ['valid Zulu text', rows[0].text === '2026-02-03 08:30:00'],
    ['valid Zulu title raw', rows[0].title === '2026-02-03T08:30:00Z'],
    ['offset -> local instant text', rows[1].text === '2026-03-14 19:32:03'],
    ['offset title raw', rows[1].title === '2026-03-15T01:02:03+05:30'],
    ['unparseable raw text', rows[2].text === '日期待补'],
    ['unparseable no title', rows[2].title === null],
    ['html-ish raw text verbatim', rows[3].text === '<b>hi</b> & "q" &lt;img&'],
    ['html-ish escaped in DOM', rows[3].html === '&lt;b&gt;hi&lt;/b&gt; &amp; "q" &amp;lt;img&amp;'],
    ['html-ish no title', rows[3].title === null],
    ['missing blank', rows[4].text === ''],
    ['missing no title', rows[4].title === null],
    ['null blank', rows[5].text === ''],
    ['null no title', rows[5].title === null],
    ['empty blank', rows[6].text === ''],
    ['empty no title', rows[6].title === null],
    ['object abnormal', rows[7].text === '字段格式异常'],
    ['object no title', rows[7].title === null],
    ['array abnormal', rows[8].text === '字段格式异常'],
    ['array no title', rows[8].title === null],
    ['table present', list.hasTable === true],
    ['no skip notice', list.skip === 0],
    ['no list error', list.err === false],
  ];

  let fail = 0;
  for (const [name, ok] of checks) {
    console.log((ok ? 'PASS' : 'FAIL') + ' - ' + name);
    if (!ok) fail++;
  }
  console.log('\nrow dump:');
  rows.forEach((r, i) => console.log(i, JSON.stringify(r)));

  // "Invalid Date"/"undefined" must never appear anywhere in the list area.
  const areaText = await page.$eval('#list-area', (el) => el.innerHTML);
  for (const bad of ['undefined', 'Invalid Date']) {
    const ok = !areaText.includes(bad);
    console.log((ok ? 'PASS' : 'FAIL') + ' - no "' + bad + '" in list area');
    if (!ok) fail++;
  }

  await browser.close();
  process.exitCode = fail ? 1 : 0;
} finally {
  proc.kill('SIGKILL');
  await rm(binDir, { recursive: true, force: true });
  await rm(dataDir, { recursive: true, force: true });
}

