diff --git a/index.html b/index.html
index e644eed..a91146a 100644
--- a/index.html
+++ b/index.html
@@ -228,13 +228,28 @@
     });
   }

-  function formatTime(iso) {
-    var d = new Date(iso);
-    if (isNaN(d.getTime())) return iso;
+  // 创建时间列的三种正常展示（对象/数组已由 buildRoomRow 统一判为异常，
+  // 不会进入这里）：
+  //   1. 能解析成有效日期的字符串：按浏览器本地时区显示
+  //      YYYY-MM-DD HH:mm:ss（带时区偏移的时间换算成实际对应的本地时刻，
+  //      不把原串里的时分当本地时间），悬浮提示保留接口返回的原始字符串；
+  //   2. 无法解析的非空字符串：原文直接显示在单元格中（textContent 保证
+  //      尖括号等字符只作为文字呈现），不替换为当前时间，不附悬浮说明；
+  //   3. 字段缺失、null 或空字符串：单元格留空且没有悬浮说明，
+  //      绝不由页面生成 undefined 或 Invalid Date。
+  function renderTimeCell(td, value) {
+    if (value == null || value === '') return;
+
+    var d = new Date(value);
+    if (isNaN(d.getTime())) {
+      td.textContent = typeof value === 'string' ? value : String(value);
+      return;
+    }
+
     var pad = function (n) { return String(n).padStart(2, '0'); };
-    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
+    td.textContent = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
       ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
-    return { text: text, title: iso };
+    td.title = typeof value === 'string' ? value : String(value);
   }

   // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
@@ -325,11 +340,7 @@
     {
       key: 'createdAt',
       label: '创建时间',
-      render: function (td, value) {
-        var t = formatTime(value || '');
-        td.textContent = t.text;
-        td.title = t.title;
-      }
+      render: renderTimeCell
       // 无 renderBad：异常创建时间只显示异常文案，不附加日期悬浮说明
       // （不设置 title）。
     }
diff --git a/ui-mixed-records.test.mjs b/ui-mixed-records.test.mjs
index 1e41114..20bdeb4 100644
--- a/ui-mixed-records.test.mjs
+++ b/ui-mixed-records.test.mjs
@@ -313,15 +313,15 @@ test('混合记录：房间对象全部按相对次序展示，非对象记录
     'mix-partial', '缺字段五子棋', '五子棋', '2 人', 'undefined 秒', '', '',
   ], '缺字段对象的单元格应沿用现有兜底显示');
   assert.equal(rows[3].badge, '');
-  // 现有兜底：缺 createdAt 时单元格文本为空，title 属性被 DOM 序列化为 "undefined"。
-  assert.equal(rows[3].timeTitle, 'undefined');
+  // 缺 createdAt 时单元格留空，且不附任何悬浮说明（不生成 undefined）。
+  assert.equal(rows[3].timeTitle, null, '缺少创建时间不应附带悬浮说明');

   // R5：空对象也是对象，同样成行且不计跳过，各单元格走兜底。
   assert.deepEqual(rows[4].cells, [
     '', '', '', ' 人', 'undefined 秒', '', '',
   ], '空对象应作为房间行并沿用现有兜底显示');
   assert.equal(rows[4].badge, '');
-  assert.equal(rows[4].timeTitle, 'undefined');
+  assert.equal(rows[4].timeTitle, null, '缺少创建时间不应附带悬浮说明');
 });

 // 数组非空但所有元素都是非对象（且刻意包含空串、0、false、空数组这些

